package com.ias.ticket;
import com.ias.trust.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.springframework.mock.web.*;
import java.nio.file.*;
import java.util.*;
import java.security.*;
import static org.junit.jupiter.api.Assertions.*;
/** Isolated H2/file evidence with explicit authorization port; not TLS/MySQL/browser acceptance. */
class FinanceVouchersTest {
 ApprovalBoundaryTest f;FinanceVouchers api;@TempDir Path root;boolean cap=true,enabled=true,scope=true,readOnly=false;String user="42";byte[] bytes;Map<String,Object> body;
 @BeforeEach void setup()throws Exception{f=new ApprovalBoundaryTest();f.prepare();f.db.execute("ALTER TABLE ticket_record ADD operation_id CHAR(36)");f.db.execute("CREATE TABLE ticket_create_operation(operation_id CHAR(36),state VARCHAR(20))");f.db.update("UPDATE ticket_record SET operation_id=?",f.operation);f.db.update("INSERT INTO ticket_create_operation VALUES(?,'COMPLETED')",f.operation);String sql=new String(getClass().getResourceAsStream("/db/migration/V14__finance_vouchers.sql").readAllBytes(),java.nio.charset.StandardCharsets.UTF_8).replace("CHARACTER SET ascii COLLATE ascii_bin","").replace("ENGINE=InnoDB","");for(String part:sql.split(";"))if(!part.isBlank())try(var ddl=f.ddlConnection.createStatement()){ddl.execute(part);}api=new FinanceVouchers(f.tickets,root,(token,csrf,write,purpose,r)->Map.of("tenantId","7","userId",user,"identityType","EMPLOYEE","enabled",enabled,"departmentEnabled",true,"companyIds",scope?List.of("9"):List.of(),"permissions",cap?(readOnly?List.of("finance.money.read"):List.of("finance.money.read","finance.money.collect","finance.money.refund")):List.of("ticket.read")));var image=new java.awt.image.BufferedImage(2,2,java.awt.image.BufferedImage.TYPE_INT_RGB);var out=new java.io.ByteArrayOutputStream();javax.imageio.ImageIO.write(image,"png",out);bytes=out.toByteArray();body=new HashMap<>(Map.of("operationId",UUID.randomUUID().toString(),"groupId",FinanceVouchers.group(7,9,f.ticket),"businessId",UUID.randomUUID().toString(),"purpose","FINANCE_COLLECTION","name","凭证.png","mediaType","image/png","size",Integer.toString(bytes.length),"sha256",HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes))));}
 @AfterEach void close()throws Exception{f.ddlConnection.close();}
 MockHttpServletRequest request(boolean write){var r=new MockHttpServletRequest();r.addHeader("Cookie","IAS-SESSION-DEV=test-session");r.addHeader("Idempotency-Key",body.get("operationId"));r.addHeader("Content-Type","image/png");if(write){r.addHeader("Origin","http://127.0.0.1:5173");r.addHeader("X-CSRF-TOKEN","test");}return r;}
 Map<String,Object> register(){return api.register(f.ticket,body,request(true));}
 Map<String,Object> upload()throws Exception{var r=request(true);r.setContent(bytes);return api.upload(f.ticket,body.get("operationId").toString(),r);}
 @Test void registrationOriginalKeyStableAndDifferentParametersConflict(){var a=register();assertEquals(a,register());assertEquals("UPLOADING",a.get("state"));assertEquals(1,f.count("ticket_finance_voucher"));body.put("name","different.png");assertEquals(409,assertThrows(Problem.class,this::register).status);assertEquals(1,f.count("ticket_finance_voucher_audit"));}
 @Test void uploadAndReplayExactlyOnePhysicalFileAndReadyAudit()throws Exception{var a=register();var b=upload();assertEquals(a.get("fileId"),b.get("fileId"));assertEquals("READY",b.get("state"));assertEquals(b,upload());assertEquals(2,f.count("ticket_finance_voucher_audit"));try(var files=Files.list(root)){assertEquals(1,files.count());}}
 @Test void movedFileAuditRollbackStaysPrivateAndSameFileRecovers()throws Exception{var a=register();f.db.execute("ALTER TABLE ticket_finance_voucher_audit ADD CONSTRAINT qa_voucher_fault CHECK(action<>'READY')");assertEquals(503,assertThrows(Problem.class,this::upload).status);assertEquals("UPLOADING",api.query(f.ticket,body.get("operationId").toString(),request(false)).get("state"));assertTrue(Files.exists(root.resolve(a.get("fileId")+".bin")));assertEquals(409,assertThrows(Problem.class,()->api.download(f.ticket,body.get("operationId").toString(),request(false),new MockHttpServletResponse())).status);f.db.execute("ALTER TABLE ticket_finance_voucher_audit DROP CONSTRAINT qa_voucher_fault");assertEquals("READY",upload().get("state"));assertEquals(2,f.count("ticket_finance_voucher_audit"));}
 @Test void currentCapabilityScopeAndOriginalActorRequired()throws Exception{register();cap=false;assertEquals(403,assertThrows(Problem.class,()->api.query(f.ticket,body.get("operationId").toString(),request(false))).status);cap=true;scope=false;assertEquals(404,assertThrows(Problem.class,this::upload).status);scope=true;user="43";assertEquals(404,assertThrows(Problem.class,this::upload).status);user="42";enabled=false;assertEquals(403,assertThrows(Problem.class,this::upload).status);}
 @Test void wrongGroupMediaAndParametersNeverRegister(){body.put("groupId",UUID.randomUUID().toString());assertEquals(404,assertThrows(Problem.class,this::register).status);body.put("groupId",FinanceVouchers.group(7,9,f.ticket));body.put("sha256","X".repeat(64));assertEquals(400,assertThrows(Problem.class,this::register).status);body.put("sha256","a".repeat(64));body.put("mediaType","text/html");assertEquals(415,assertThrows(Problem.class,this::register).status);assertEquals(0,f.count("ticket_finance_voucher"));}
 @Test void mismatchBytesDoNotPublishOrDeleteOriginal()throws Exception{var a=register();bytes[0]=0;assertEquals(409,assertThrows(Problem.class,this::upload).status);assertFalse(Files.exists(root.resolve(a.get("fileId")+".bin")));assertEquals("UPLOADING",api.query(f.ticket,body.get("operationId").toString(),request(false)).get("state"));try(var files=Files.list(root)){assertEquals(0,files.count());}}
 @Test void currentAuthorizedRangeAndDeniedRangeNeverWritesBody()throws Exception{register();upload();var r=request(false);r.addHeader("Range","bytes=2-5");var response=new MockHttpServletResponse();api.download(f.ticket,body.get("operationId").toString(),r,response);assertEquals(206,response.getStatus());assertArrayEquals(Arrays.copyOfRange(bytes,2,6),response.getContentAsByteArray());cap=false;var denied=new MockHttpServletResponse();assertEquals(403,assertThrows(Problem.class,()->api.download(f.ticket,body.get("operationId").toString(),r,denied)).status);assertEquals(0,denied.getContentAsByteArray().length);}
 @Test void strictRanges(){assertArrayEquals(new long[]{7,9},FinanceVouchers.range(List.of("bytes=-3"),10));for(String s:List.of("bytes=10-","bytes=1-0","bytes=1-2,4-5","bytes=-0","bytes=-"))assertEquals(416,assertThrows(Problem.class,()->FinanceVouchers.range(List.of(s),10)).status);assertEquals(416,assertThrows(Problem.class,()->FinanceVouchers.range(List.of("bytes=1-2","bytes=3-4"),10)).status);}
 @Test void factIsExactCurrentBoundAvailableNotMoney()throws Exception{var a=register();upload();var b=new HashMap<String,Object>(Map.of("sessionToken","test","ticketId",f.ticket,"groupId",body.get("groupId"),"companyId","9","businessId",body.get("businessId"),"fileId",a.get("fileId"),"purpose",body.get("purpose"),"evidenceDigest",body.get("sha256")));user="43";var fact=api.factRead(b,request(false));assertEquals("AVAILABLE",fact.get("state"));assertEquals("43",fact.get("actorUserId"));assertFalse(fact.containsKey("received"));b.put("businessId",UUID.randomUUID().toString());assertEquals(404,assertThrows(Problem.class,()->api.factRead(b,request(false))).status);}
 @Test void correctionRequiresReverseAndExactReviewEvidence()throws Exception{
  try(var ddl=f.ddlConnection.createStatement()){ddl.execute("ALTER TABLE ticket_finance_voucher DROP CONSTRAINT ck_finance_voucher_purpose");ddl.execute("ALTER TABLE ticket_finance_voucher ADD CONSTRAINT ck_finance_voucher_purpose CHECK(purpose IN ('FINANCE_COLLECTION','FINANCE_REFUND','FINANCE_CORRECTION'))");}
  api=new FinanceVouchers(f.tickets,root,(token,csrf,write,purpose,r)->Map.of("tenantId","7","userId",user,"identityType","EMPLOYEE","enabled",true,"departmentEnabled",true,"companyIds",scope?List.of("9"):List.of(),"permissions",cap?List.of("finance.money.read","finance.money.reverse"):List.of("finance.money.read","finance.money.collect")));
  body.put("purpose","FINANCE_CORRECTION");cap=false;assertEquals(403,assertThrows(Problem.class,this::register).status);cap=true;var registered=register();upload();
  var b=new HashMap<String,Object>(Map.of("sessionToken","test","ticketId",f.ticket,"groupId",body.get("groupId"),"companyId","9","businessId",body.get("businessId"),"fileId",registered.get("fileId"),"purpose",body.get("purpose"),"evidenceDigest",body.get("sha256")));
  assertEquals("AVAILABLE",api.factRead(b,request(false)).get("state"));b.put("businessId",UUID.randomUUID().toString());assertEquals(404,assertThrows(Problem.class,()->api.factRead(b,request(false))).status);
 }
 @Test void anotherScopedFinanceReaderDownloadsStableFileWithoutWriteCapability()throws Exception{var a=register();upload();user="43";readOnly=true;var r=request(false);r.setMethod("HEAD");var response=new MockHttpServletResponse();api.stableDownload(f.ticket,a.get("fileId").toString(),r,response);assertEquals(bytes.length,response.getContentLengthLong());assertEquals(0,response.getContentAsByteArray().length);r.setMethod("GET");var get=new MockHttpServletResponse();api.stableDownload(f.ticket,a.get("fileId").toString(),r,get);assertArrayEquals(bytes,get.getContentAsByteArray());scope=false;var denied=new MockHttpServletResponse();assertEquals(404,assertThrows(Problem.class,()->api.stableDownload(f.ticket,a.get("fileId").toString(),r,denied)).status);assertEquals(0,denied.getContentAsByteArray().length);}
 @Test void concurrentOriginalFileUploadsHaveOneReadyFact()throws Exception{register();try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var gate=new java.util.concurrent.CountDownLatch(1);var a=pool.submit(()->{gate.await();return upload();});var b=pool.submit(()->{gate.await();return upload();});gate.countDown();assertEquals("READY",a.get().get("state"));assertEquals("READY",b.get().get("state"));}assertEquals(2,f.count("ticket_finance_voucher_audit"));try(var files=Files.list(root)){assertEquals(1,files.count());}}
 @Test void wrongMagicOrContentTypeNeverPublishes()throws Exception{body.put("mediaType","application/pdf");register();var r=request(true);r.removeHeader("Content-Type");r.addHeader("Content-Type","application/pdf");r.setContent(bytes);assertEquals(415,assertThrows(Problem.class,()->api.upload(f.ticket,body.get("operationId").toString(),r)).status);assertEquals("UPLOADING",api.query(f.ticket,body.get("operationId").toString(),request(false)).get("state"));}
 @Test void readyRowWithoutPhysicalEvidenceFailsClosed()throws Exception{var a=register();upload();Files.delete(root.resolve(a.get("fileId")+".bin"));var b=new HashMap<String,Object>(Map.of("sessionToken","test","ticketId",f.ticket,"groupId",body.get("groupId"),"companyId","9","businessId",body.get("businessId"),"fileId",a.get("fileId"),"purpose",body.get("purpose"),"evidenceDigest",body.get("sha256")));assertEquals(503,assertThrows(Problem.class,()->api.factRead(b,request(false))).status);var response=new MockHttpServletResponse();assertThrows(java.io.IOException.class,()->api.stableDownload(f.ticket,a.get("fileId").toString(),request(false),response));assertEquals(0,response.getContentAsByteArray().length);}
}
